// builtin. Iteration is by CODE POINT (not UTF-16 unit) so astral characters
// stay literal and unpaired surrogates (produced by argv surrogateescape
// decoding) render as `\udcff`-style escapes.

import { PyTypeError } from './errors.mjs';
import { isPrintableCodePoint, toCodePoints } from './unicode.mjs';

/**
 * Format one non-printable code point the way CPython's repr does:
 * `\xHH` for <= 0xFF, `\uHHHH` for <= 0xFFFF, `\UHHHHHHHH` otherwise.
 * Hex digits are LOWERCASE (verified against the reference: `'\x1f5'`,
 * `'​'`, `'\U000e0001'`).
 */
function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python `repr(s)` for a str.
 *
 * CPython chooses the quote character first: `'` normally, but `"` when the
 * string contains a `'` and no `"` (so the apostrophe needs no escaping).
 * Then, per code point: the active quote and backslash are backslash-escaped,
 * tab/newline/carriage-return get their short escapes, anything that
 * `str.isprintable()` rejects becomes a numeric escape, and everything else is
 * emitted literally.
 */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  const out = [quote];
  for (const cp of toCodePoints(s)) {
    // Backslash and the active quote: `\\` and e.g. `\'`.
    if (cp === 0x5c /* \ */) {
      out.push('\\\\');
    } else if (String.fromCodePoint(cp) === quote) {
      out.push('\\' + quote);
    } else if (cp === 0x09) {
      out.push('\\t');
    } else if (cp === 0x0a) {
      out.push('\\n');
    } else if (cp === 0x0d) {
      out.push('\\r');
    } else if (!isPrintableCodePoint(cp)) {
      // Covers ASCII controls and DEL (Cc), Cf/Cs/Co/Cn, Zl/Zp and the
      // non-U+0020 Zs characters -- exactly Python's isprintable() complement.
      out.push(escapeCodePoint(cp));
    } else {
      out.push(String.fromCodePoint(cp));
    }
