import { readFileSync } from 'node:fs';
import { pyIntFromString } from './py/int.mjs';
import { reprStr, pyStr } from './py/repr.mjs';
import { PyValueError } from './py/errors.mjs';

function decodeSE(bytes) {
  let out = '';
  for (let i = 0; i < bytes.length; ) {
    const b = bytes[i];
    if (b < 0x80) { out += String.fromCharCode(b); i++; continue; }
    let len = 0, cp = 0;
    if (b >= 0xc2 && b <= 0xdf) { len = 2; cp = b & 0x1f; }
    else if (b >= 0xe0 && b <= 0xef) { len = 3; cp = b & 0x0f; }
    else if (b >= 0xf0 && b <= 0xf4) { len = 4; cp = b & 0x07; }
    else { out += String.fromCharCode(0xdc00 + b); i++; continue; }
    let ok = i + len <= bytes.length, v = cp;
    if (ok) {
      for (let k = 1; k < len; k++) {
        const c = bytes[i + k];
        if ((c & 0xc0) !== 0x80) { ok = false; break; }
        v = (v << 6) | (c & 0x3f);
      }
    }
    if (!ok || v > 0x10ffff || (v >= 0xd800 && v <= 0xdfff) ||
        (len === 2 && v < 0x80) || (len === 3 && v < 0x800) || (len === 4 && v < 0x10000)) {
      out += String.fromCharCode(0xdc00 + b); i++; continue;
    }
    out += String.fromCodePoint(v); i += len;
  }
  return out;
}
function encodeSE(str) {
  const parts = [];
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (cp >= 0xdc80 && cp <= 0xdcff) parts.push(Buffer.from([cp - 0xdc00]));
    else parts.push(Buffer.from(ch, 'utf8'));
  }
  return Buffer.concat(parts);
}

